paragraph.math:
$$\boxed{\begin{array}{l}
      {\lbrack\begin{array}{rrrr}
      u_{1} & u_{2} & \cdots & {u_{n}}
      \end{array}\rbrack~\left\lbrack \begin{array}{r}
      v_{1} \\
      v_{2} \\
       \vdots \\
      v_{n}
      \end{array} \right\rbrack = u_{1}v_{1} + u_{2}v_{2} + \cdots + u_{n}v_{n}}
      \end{array}}$$

$$\begin{matrix}
      {\text{dist~}\left( \mathbf{u}\text{,~}\mathbf{v} \right)} & = & {\text{∥}\mathbf{u} - \mathbf{v}\text{∥} = \sqrt{\text{(}\mathbf{u} - \mathbf{v}\text{)} \cdot \text{(}\mathbf{u} - \mathbf{v}\text{)}}} \\
       & = & \sqrt{\left( u_{1} - v_{1} \right)^{2} + \left( u_{2} - v_{2} \right)^{2} + \left( u_{3} - v_{3} \right)^{2}}
      \end{matrix}$$

$$\begin{matrix}
      {\text{∥}\mathbf{u}\text{∥~}\text{∥}\mathbf{v}\text{∥cos~}\vartheta} & = & {\frac{1}{2}\left\lbrack \text{∥}\mathbf{u}\text{∥}^{2} + \text{∥}\mathbf{v}\text{∥}^{2} - \text{∥}\mathbf{u} - \mathbf{v}\text{∥}^{2} \right\rbrack} \\
       & = & {\frac{1}{2}\left\lbrack {u_{1}^{2} + u_{2}^{2} + v_{1}^{2} + v_{2}^{2} - \left( u_{1} - v_{1} \right)^{2} - \left( u_{2} - v_{2} \right)^{2}} \right\rbrack} \\
       & = & {u_{1}v_{1} + u_{2}v_{2}} \\
       & = & {\mathbf{u} \cdot \mathbf{v}}
      \end{matrix}$$

statement.paragraph:
Find the distance between $\textbf{x} = \left\lbrack \begin{array}{r}
      10 \\
      {- 3}
      \end{array} \right\rbrack$ and $\textbf{y} = \left\lbrack \begin{array}{r}
      {- 1} \\
      {- 5}
      \end{array} \right\rbrack$.

$\textbf{a} = \left\lbrack \begin{array}{r}
      8 \\
      {- 5}
      \end{array} \right\rbrack$, $\textbf{b} = \left\lbrack \begin{array}{r}
      {- 2} \\
      {- 3}
      \end{array} \right\rbrack$

$\mathbf{u} = \left\lbrack \begin{array}{r}
      12 \\
      3 \\
      {- 5}
      \end{array} \right\rbrack$, $\mathbf{v} = \left\lbrack \begin{array}{r}
      2 \\
      {- 3} \\
      3
      \end{array} \right\rbrack$

Let $\mathbf{u} = \left\lbrack \begin{array}{r}
      2 \\
      {- 5} \\
      {- 1}
      \end{array} \right\rbrack$ and $\mathbf{v} = \left\lbrack \begin{array}{r}
      {- 7} \\
      {- 4} \\
      6
      \end{array} \right\rbrack$. Compute and compare $\mathbf{u} \cdot \mathbf{v}$, $\text{∥}\textbf{u}\text{∥}^{2}$, $\text{∥}\textbf{v}\text{∥}^{2}$, and $\text{∥}\mathbf{u} + \mathbf{v}\text{∥}^{2}$. Do not use the Pythagorean Theorem.
